head.script:
  /**/
  (function () {
  const { search, hash, pathname } = window.location;

  // 条件1: URL 中包含 ?sc=... 查询参数
  const hasSuccessParam = search.includes('sc=');

  // 条件2: URL 中包含 #c... 哈希
  const hasCommentHash = hash.startsWith('#c');

  // 条件3 (备用): 检查旧的 window.name 方式，作为补充
  const hasSuccessName = pathname.startsWith('new-comment-');

  // 如果满足URL条件，或者满足备用的 window.name 条件，就认为是成功弹窗
  const isCommentSuccessPopup = (hasSuccessParam && hasCommentHash) || hasSuccessName;
  if (isCommentSuccessPopup) {
  window.close();
  }
  try {
  // 从 localStorage 获取主题
  let theme = localStorage.getItem('theme');

  // 如果没有手动设置主题，才使用系统偏好
  if (theme === null || theme === undefined) {
  const prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
  theme = prefersDark ? 'dark' : 'light';
  }

  // 立即设置主题属性，让CSS立即生效
  if (theme === 'dark') {
  document.documentElement.setAttribute('theme-mode', 'dark');
  } else {
  document.documentElement.removeAttribute('theme-mode');
  }

  // 在页面加载完成后移除阻塞样式，让正常的CSS接管
  function enableTransitions() {
  const blockingStyles = document.getElementById('theme-blocking-styles');
  if (blockingStyles) {
  blockingStyles.remove();
  }
  }

  // 在DOMContentLoaded和load事件后都尝试移除，确保React应用启动后
  if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', enableTransitions);
  window.addEventListener('load', enableTransitions);
  } else {
  enableTransitions();
  }

  } catch (e) {
  // 出现错误时，设置默认浅色主题
  document.documentElement.removeAttribute('theme-mode');
  }
  })();
/**/

head.b:skin:
/* ================= 基础 ================= */
* { box-sizing: border-box; }
body {
  background-color: var(--bg-color, #f5f5f9);
  color: var(--text-color, #212529);
  font-family: 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', Arial, sans-serif;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}
a { color: inherit; text-decoration: none; }
img { max-width: 100%; height: auto; }
.widget { margin: 0; }
.section { margin: 0; padding: 0; }

/* ================= 顶部导航（原生渲染，主题切换为 React 岛屿） ================= */
.site-nav {
  position: sticky; top: 0; z-index: 100;
  background: var(--surface-color, #ececf3);
  border-bottom: 1px solid var(--border-color, #82969f);
  box-shadow: 0 2px 4px var(--shadow-color, rgba(0, 0, 0, 0.1));
}
.site-nav__inner {
  max-width: 1200px; margin: 0 auto; height: 60px; padding: 0 24px;
  display: flex; align-items: center; gap: 24px;
}
.site-nav__brand { font-size: 18px; font-weight: 700; white-space: nowrap; }
.site-nav__links {
  display: flex; align-items: center; gap: 20px; flex: 1; min-width: 0;
  overflow-x: auto; scrollbar-width: none; -ms-overflow-style: none;
}
.site-nav__links::-webkit-scrollbar { display: none; }
.site-nav__link {
  font-size: 14px; font-weight: 600; letter-spacing: 0.05em; white-space: nowrap;
  padding: 4px 2px; border-bottom: 2px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}
.site-nav__link:hover { color: var(--primary-color, #82969f); border-bottom-color: var(--primary-color, #82969f); }
.site-nav__tools { display: flex; align-items: center; gap: 12px; }
.site-nav__search { display: flex; align-items: center; gap: 6px; }
.site-nav__search input {
  width: 140px; padding: 6px 12px; font-size: 13px;
  color: var(--text-color, #212529); background: var(--bg-color, #f5f5f9);
  border: 1px solid var(--border-color, #82969f); border-radius: 999px;
  outline: none; transition: width 0.25s, border-color 0.2s;
}
.site-nav__search input:focus { width: 200px; border-color: var(--primary-color, #82969f); }
.site-nav__search button {
  display: inline-flex; align-items: center; justify-content: center;
  width: 32px; height: 32px; border: none; border-radius: 50%;
  background: transparent; color: var(--text-secondary-color, #627077); cursor: pointer;
}
.site-nav__search button:hover { color: var(--primary-color, #82969f); background: var(--bg-color, #f5f5f9); }
#react-theme { display: inline-flex; }

/* ================= 主页 / 列表页 ================= */
.home { padding: 40px 24px 64px; }
.home__inner { max-width: 1200px; margin: 0 auto; }
.home__hero { padding: 16px 0 28px; margin-bottom: 32px; border-bottom: 1px solid var(--border-color, #82969f); }
.home__title { margin: 0 0 12px; font-size: 40px; font-weight: 800; letter-spacing: -0.02em; line-height: 1.2; }
.home__desc { margin: 0; max-width: 720px; color: var(--text-secondary-color, #627077); font-size: 15px; }
.home__body { display: flex; gap: 40px; align-items: flex-start; }
.home__main { flex: 1; min-width: 0; }
.home__list-head { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 20px; }
.home__list-title { margin: 0; font-size: 20px; font-weight: 700; }
.post-grid { display: grid; grid-template-columns: 1fr; gap: 16px; }
@media (min-width: 768px) { .post-grid { grid-template-columns: 1fr 1fr; } }
.post-card {
  background: var(--surface-color, #ececf3);
  border: 1px solid var(--border-color, #82969f);
  border-radius: 10px;
  box-shadow: 0 2px 8px var(--shadow-color, rgba(0, 0, 0, 0.08));
  transition: transform 0.2s, box-shadow 0.2s;
}
.post-card:hover { transform: translateY(-2px); box-shadow: 0 6px 16px var(--shadow-color, rgba(0, 0, 0, 0.12)); }
.post-card__link { display: block; padding: 20px; }
.post-card__meta { display: flex; align-items: center; gap: 8px; margin-bottom: 10px; font-size: 12px; color: var(--text-secondary-color, #627077); }
.post-card__tag {
  padding: 2px 10px; border-radius: 999px; font-weight: 600;
  background: var(--primary-color, #82969f); color: var(--surface-color, #ececf3);
}
.post-card__title { margin: 0 0 8px; font-size: 18px; font-weight: 700; line-height: 1.35; }
.post-card:hover .post-card__title { color: var(--primary-color, #82969f); }
.post-card__snippet {
  margin: 0; font-size: 14px; color: var(--text-secondary-color, #627077);
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
}
.pager { display: flex; justify-content: center; gap: 16px; margin-top: 36px; }
.pager__btn {
  padding: 8px 22px; border: 1px solid var(--border-color, #82969f); border-radius: 999px;
  font-size: 14px; font-weight: 600; transition: background 0.2s, color 0.2s;
}
.pager__btn:hover { background: var(--primary-color, #82969f); color: var(--surface-color, #ececf3); }
.home__side { flex: 0 0 300px; position: sticky; top: 84px; min-width: 0; }
@media (max-width: 1024px) {
  .home__body { flex-direction: column; }
  .home__side { flex: none; width: 100%; position: static; }
}

/* ================= 文章 / 页面详情 ================= */
.post-detail { padding: 48px 24px 72px; }
.post-detail__header { max-width: 900px; margin: 0 auto 36px; }
.post-detail__label {
  display: inline-block; margin-bottom: 12px; font-size: 13px; font-weight: 700;
  letter-spacing: 0.08em; text-transform: uppercase; color: var(--primary-color, #82969f);
}
.post-detail__title { margin: 0 0 24px; font-size: 40px; line-height: 1.2; font-weight: 800; word-break: break-word; }
.post-detail__meta { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px 24px; padding-top: 20px; border-top: 1px solid var(--border-color, #82969f); }
@media (min-width: 768px) { .post-detail__meta { grid-template-columns: repeat(4, 1fr); } }
.post-detail__meta-item { display: flex; flex-direction: column; gap: 4px; font-size: 14px; min-width: 0; }
.post-detail__meta-label { font-size: 11px; font-weight: 700; letter-spacing: 0.1em; color: var(--text-secondary-color, #627077); }
.post-detail__meta-value { font-weight: 600; word-break: break-word; }
.post-detail__meta-value a:hover { color: var(--primary-color, #82969f); }
.post-detail__share { color: var(--primary-color, #82969f); font-weight: 700; cursor: pointer; }
.post-detail__share:hover { text-decoration: underline; }
.post-detail__cover { max-width: 1200px; margin: 0 auto 40px; border-radius: 12px; overflow: hidden; }
.post-detail__layout { max-width: 900px; margin: 0 auto; }
/* 桌面端为左侧常驻目录预留空间（变量由 toc.css 定义，窄视口自动归零） */
@media (min-width: 1025px) {
  .post-detail__layout { padding-left: calc(var(--toc-panel-left, 24px) + var(--toc-panel-width, 248px) + 32px); }
}
.post-detail__content { min-width: 0; }

/* 正文兜底排版：细化样式由 PostBodyEnhancer 岛屿注入的 .blog-content 规则提供 */
.post-body { font-size: 17px; line-height: 1.8; overflow-wrap: break-word; }
.post-body h1, .post-body h2, .post-body h3, .post-body h4 { margin: 1.5em 0 0.8em; line-height: 1.3; }
.post-body img { border-radius: 8px; margin: 1rem 0; cursor: zoom-in; }
.post-body pre { padding: 1rem; border-radius: 8px; overflow-x: auto; background: rgba(127, 127, 127, 0.12); }
.post-body code { font-family: 'JetBrains Mono', Consolas, Monaco, 'Courier New', monospace; }
.post-body blockquote {
  margin: 1rem 0; padding: 0.5rem 1rem; border-left: 4px solid var(--primary-color, #82969f);
  border-radius: 4px; color: var(--text-secondary-color, #627077); background: var(--surface-color, #ececf3);
}
.post-body table { width: 100%; border-collapse: collapse; }
.post-body th, .post-body td { border: 1px solid var(--border-color, #82969f); padding: 0.5rem 0.75rem; }

/* ================= 原生评论 ================= */
.post-detail__comments { max-width: 900px; margin: 56px auto 0; padding-top: 32px; border-top: 1px solid var(--border-color, #82969f); }
#comments h3 { display: flex; align-items: center; gap: 8px; font-size: 18px; font-weight: 800; margin: 0 0 24px; }
#comments h3::before { content: ''; width: 8px; height: 8px; border-radius: 50%; background: var(--primary-color, #82969f); }
.comment { margin-bottom: 28px; }
.comment-block { margin-left: 16px; }
.comment-header { display: flex; align-items: baseline; flex-wrap: wrap; gap: 8px; margin-bottom: 6px; }
.comment-author { font-weight: 700; font-style: normal; }
.comment-author a { color: inherit; }
.comment-timestamp { font-size: 12px; color: var(--text-secondary-color, #627077); }
.comment-timestamp a { color: inherit; }
.comment-body { font-size: 15px; line-height: 1.6; }
.comment-body p { margin: 0 0 0.5em; }
.avatar-image-container img { border-radius: 50%; width: 40px; height: 40px; border: 2px solid var(--surface-color, #ececf3); }
.comment-actions a, .comment-reply-link, .comment-footer a {
  display: inline-block; margin: 8px 8px 0 0; padding: 4px 14px;
  font-size: 12px; font-weight: 700; color: var(--primary-color, #82969f);
  border: 1px solid var(--primary-color, #82969f); border-radius: 999px;
  text-decoration: none; transition: background 0.2s, color 0.2s;
}
.comment-actions a:hover, .comment-reply-link:hover, .comment-footer a:hover {
  background: var(--primary-color, #82969f); color: var(--surface-color, #ececf3);
}
.comment-form h4 { font-size: 16px; font-weight: 800; margin: 24px 0 12px; }
.comments .paging-control-container { display: flex; gap: 12px; align-items: center; font-size: 13px; margin: 16px 0; }

/* ================= 页脚 ================= */
.site-footer { border-top: 1px solid var(--border-color, #82969f); background: var(--surface-color, #ececf3); padding: 28px 24px; margin-top: auto; }
.site-footer__inner {
  max-width: 1200px; margin: 0 auto; display: flex; flex-wrap: wrap;
  justify-content: space-between; gap: 20px; font-size: 13px; color: var(--text-secondary-color, #627077);
}
.site-footer__brand { font-size: 18px; font-weight: 800; color: var(--text-color, #212529); }
.site-footer__col { display: flex; flex-direction: column; gap: 6px; }
.site-footer a:hover { color: var(--primary-color, #82969f); }

/* ================= 复制链接 Toast ================= */
#copy-toast {
  position: fixed; left: 50%; bottom: 32px; transform: translateX(-50%); z-index: 200;
  padding: 10px 22px; border-radius: 999px; font-size: 13px; font-weight: 600;
  background: var(--text-color, #212529); color: var(--bg-color, #f5f5f9);
  opacity: 0; visibility: hidden; box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);
  transition: opacity 0.3s, bottom 0.3s, visibility 0.3s;
}
#copy-toast.show { opacity: 1; visibility: visible; bottom: 48px; }

body.script:
//
function showCopyToast() {
  var toast = document.getElementById('copy-toast');
  if (!toast) return;
  toast.classList.add('show');
  setTimeout(function () { toast.classList.remove('show'); }, 2000);
}
function copyPostLink() {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(window.location.href).then(showCopyToast, showCopyToast);
  } else {
    showCopyToast();
  }
}
var yearEl = document.getElementById('current-year');
if (yearEl) yearEl.innerText = new Date().getFullYear();
//
